import json
from itertools import permutations

def solve():
    houses = [1, 2, 3]

    categories = {
        "Name": ["Arnold", "Eric", "Peter"],
        "favorite cigar": ["pall mall", "blue master", "prince"],
        "animals": ["horse", "cat", "bird"],
        "child": ["Bella", "Fred", "Meredith"],
        "favorite book genres": ["science fiction", "romance", "mystery"],
        "phone models": ["google pixel 6", "iphone 13", "samsung galaxy s21"],
    }

    # Helpers to evaluate constraints on a partial assignment
    def house_of(pos, category, value):
        if category in pos and value in pos[category]:
            return pos[category][value]
        return None

    def assert_same_house(pos, c1, v1, c2, v2):
        h1 = house_of(pos, c1, v1)
        h2 = house_of(pos, c2, v2)
        if h1 is not None and h2 is not None:
            return h1 == h2
        return True

    def assert_not_house(pos, c, v, h):
        hh = house_of(pos, c, v)
        if hh is not None:
            return hh != h
        return True

    def assert_house(pos, c, v, h):
        hh = house_of(pos, c, v)
        if hh is not None:
            return hh == h
        return True

    def assert_left(pos, c1, v1, c2, v2, direct=False):
        h1 = house_of(pos, c1, v1)
        h2 = house_of(pos, c2, v2)
        if h1 is None or h2 is None:
            return True
        if direct:
            return h1 + 1 == h2
        return h1 < h2

    def check_constraints(pos):
        # 1. The person who loves mystery books is the person's child is named Fred.
        if not assert_same_house(pos, "favorite book genres", "mystery", "child", "Fred"):
            return False

        # 2. The cat lover is Eric.
        if not assert_same_house(pos, "animals", "cat", "Name", "Eric"):
            return False

        # 3. The person partial to Pall Mall is in the second house.
        if not assert_house(pos, "favorite cigar", "pall mall", 2):
            return False

        # 4. The person who keeps horses is the person's child is named Meredith.
        if not assert_same_house(pos, "animals", "horse", "child", "Meredith"):
            return False

        # 5. The person's child is named Bella is the Prince smoker.
        if not assert_same_house(pos, "child", "Bella", "favorite cigar", "prince"):
            return False

        # 6. The person who uses an iPhone 13 is directly left of the person who uses a Samsung Galaxy S21.
        if not assert_left(pos, "phone models", "iphone 13", "phone models", "samsung galaxy s21", direct=True):
            return False

        # 7. The person's child is named Fred is directly left of Arnold.
        if not assert_left(pos, "child", "Fred", "Name", "Arnold", direct=True):
            return False

        # 8. Peter is somewhere to the left of Eric.
        if not assert_left(pos, "Name", "Peter", "Name", "Eric", direct=False):
            return False

        # 9. The person who loves science fiction books is the person who uses a Samsung Galaxy S21.
        if not assert_same_house(pos, "favorite book genres", "science fiction", "phone models", "samsung galaxy s21"):
            return False

        # 10. The person who loves science fiction books is in the third house.
        if not assert_house(pos, "favorite book genres", "science fiction", 3):
            return False

        # 11. The person who loves mystery books is not in the second house.
        if not assert_not_house(pos, "favorite book genres", "mystery", 2):
            return False

        return True

    # Backtracking search over permutations for each category with pruning
    solution_pos = None

    phones_vals = categories["phone models"]
    books_vals = categories["favorite book genres"]
    names_vals = categories["Name"]
    child_vals = categories["child"]
    cigars_vals = categories["favorite cigar"]
    animals_vals = categories["animals"]

    for phones_perm in permutations(houses):
        pos = {
            "phone models": dict(zip(phones_vals, phones_perm))
        }
        if not check_constraints(pos):
            continue

        for books_perm in permutations(houses):
            pos2 = dict(pos)
            pos2["favorite book genres"] = dict(zip(books_vals, books_perm))
            if not check_constraints(pos2):
                continue

            for names_perm in permutations(houses):
                pos3 = dict(pos2)
                pos3["Name"] = dict(zip(names_vals, names_perm))
                if not check_constraints(pos3):
                    continue

                for child_perm in permutations(houses):
                    pos4 = dict(pos3)
                    pos4["child"] = dict(zip(child_vals, child_perm))
                    if not check_constraints(pos4):
                        continue

                    for cigar_perm in permutations(houses):
                        pos5 = dict(pos4)
                        pos5["favorite cigar"] = dict(zip(cigars_vals, cigar_perm))
                        if not check_constraints(pos5):
                            continue

                        for animals_perm in permutations(houses):
                            pos6 = dict(pos5)
                            pos6["animals"] = dict(zip(animals_vals, animals_perm))
                            if not check_constraints(pos6):
                                continue
                            solution_pos = pos6
                            break
                        if solution_pos:
                            break
                    if solution_pos:
                        break
                if solution_pos:
                    break
            if solution_pos:
                break
        if solution_pos:
            break

    if not solution_pos:
        raise RuntimeError("No solution found")

    # Invert value->house to house->value for output
    def invert(cat):
        return {h: v for v, h in solution_pos[cat].items()}

    house_to_name = invert("Name")
    house_to_cigar = invert("favorite cigar")
    house_to_animal = invert("animals")
    house_to_child = invert("child")
    house_to_books = invert("favorite book genres")
    house_to_phone = invert("phone models")

    header = ["House", "Name", "favorite cigar", "animals", "child", "favorite book genres", "phone models"]
    rows = []
    for h in sorted(houses):
        rows.append([
            str(h),
            house_to_name[h],
            house_to_cigar[h],
            house_to_animal[h],
            house_to_child[h],
            house_to_books[h],
            house_to_phone[h],
        ])

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    solve()
